(function(root){
'use strict';
const classes={fighter:{name:'Fighter',hp:24,ac:16,stats:{STR:3,DEX:1,CON:2,INT:0,WIS:1,CHA:0},attack:5,die:8,damage:3,weapon:'Longsword',ability:'Second Wind: once per adventure, restore 1d10 + 2 HP without spending your action. Power strike: attack at −2 to hit for +4 damage (house rule).'},rogue:{name:'Rogue',hp:18,ac:14,stats:{STR:0,DEX:3,CON:1,INT:1,WIS:1,CHA:2},attack:5,die:6,damage:3,weapon:'Shortbow',ability:'Hide: Dexterity + proficiency against DC 11. On success, the next attack has advantage and adds 1d6 sneak damage. Hiding consumes your action; a successful hide avoids the enemy’s next attack (solo house rule).'},wizard:{name:'Wizard',hp:14,ac:12,stats:{STR:-1,DEX:2,CON:1,INT:3,WIS:1,CHA:0},attack:5,die:10,damage:0,weapon:'Fire Bolt',ability:'Three spell slots. Magic Missile: three darts, each 1d4 + 1, automatically hit. Ward: spend a slot to restore 1d8 + 3 HP and gain +5 AC against the next attack (custom spell). Fire Bolt costs no slots.'}};
const O=(id,label,hint,next,check=null,success=null,fail=null)=>({id,label,hint,next,check,success,fail});
const scenes={
road:{title:'The road to Blackthorn',chapter:'I / THE THIRTEENTH TOLL',text:'Rain beads on your cloak. Ahead, the village of Blackthorn huddles beneath a ruined abbey. Its bell tower has no bell.\n\nA woman stands in the road holding a lantern and a muddy child’s shoe.\n\n“My daughter went after the others,” she says. “They walked out of their graves. Not towards us. Towards the abbey.”\n\nFrom under the earth comes a single, impossibly deep note.',options:[O('promise','Promise to find her daughter','A promise is a kind of magic.','square',null,'promise'),O('question','Ask what the dead were carrying','Notice what fear overlooks.','square',null,'clue')]},
square:{title:'A village holding its breath',chapter:'I / THE THIRTEENTH TOLL',text:'The Crooked Lantern is barricaded. A young gravekeeper, Tamsin, sharpens a shovel on its doorstep.\n\n“Everyone says the dead are attacking,” she says. “But they took flowers. Who brings flowers to a battle?”\n\nShe offers you a brass token stamped with a name: EDRIN. The old bellkeeper.\n\nYou have time to investigate one lead before the procession reaches the abbey.',options:[O('tavern','Speak to the innkeeper','Persuasion · CHA + proficiency · DC 11','gate',{stat:'CHA',dc:11,prof:true},'supplies','rumour'),O('graves','Read the opened graves','Investigation · INT + proficiency · DC 12','gate',{stat:'INT',dc:12,prof:true},'oath','gravefail'),O('tracks','Follow the smallest footprints','Survival · WIS + proficiency · DC 11','gate',{stat:'WIS',dc:11,prof:true},'child','trackfail')]},
gate:{title:'The abbey gate',chapter:'II / STONE & SHADOW',text:'An armoured skeleton kneels beneath the gate, tying flowers to a rusted spear. At your approach it rises.\n\n“None may disturb the bellkeeper’s vigil.”\n\nAbove its shoulder, a narrow breach opens into the cloister. Beneath its breastplate, something glows with the colour of a dying coal.',options:[O('honour','Show Edrin’s token','Appeal to the guardian’s oath.','cloister',null,'token'),O('sneak','Slip through the breach','Stealth · DEX + proficiency · DC 12','cloister',{stat:'DEX',dc:12,prof:true},'sneak','guardfight'),O('fight','Challenge the guardian','Combat · grave sentinel · AC 12','cloister',null,'guardfight')]},
cloister:{title:'Where the living hide',chapter:'II / STONE & SHADOW',text:'Moonlight collects in the roofless cloister. A little girl sits beside a skeleton in a gardener’s apron. Together, they are making a crown of weeds.\n\n“This is my grandad,” she tells you. “He says he can’t go home until Edrin stops ringing.”\n\nThe skeleton cups its hands over ears it no longer has. Below you, the bell sounds again.',options:[O('escort','Lead the girl back to the gate','Keep someone safe before going deeper.','archive',null,'rescue'),O('ask','Ask her grandfather about Edrin','Religion · WIS + proficiency · DC 11','archive',{stat:'WIS',dc:11,prof:true},'oath','whisper'),O('listen','Listen beneath the stone','Arcana · INT + proficiency · DC 12','archive',{stat:'INT',dc:12,prof:true},'trueName','ache')]},
archive:{title:'The keeper’s archive',chapter:'II / STONE & SHADOW',text:'The archive smells of wet paper and candle wax. A ledger lies open beside a silver tuning fork.\n\nThe final entry reads: “The bell holds the names of those we refuse to lose. One name remains.”\n\nA narrow stair descends to the flooded crypt. The ceiling shudders. You can take one thing before it comes down.',options:[O('ledger','Save the ledger','Learn the name grief left behind.','crypt',null,'trueName'),O('fork','Take the silver tuning fork','A tool for breaking an enchantment.','crypt',null,'fork'),O('cache','Break open the healer’s cabinet','Gain two healing potions.','crypt',null,'cache')]},
crypt:{title:'The drowned stair',chapter:'III / WHAT THE DEAD ARE OWED',text:'Black water covers the steps. Something pale moves beneath it. On the opposite landing, a door bears seven iron locks, all hanging open.\n\nA thread of bell-song passes through the water. Wherever it touches, shapes begin to rise.',options:[O('cross','Leap across the broken balustrade','Athletics · STR + proficiency · DC 12','threshold',{stat:'STR',dc:12,prof:true},'cross','drownfight'),O('dispel','Disrupt the song’s pattern','Arcana · INT + proficiency · DC 12; tuning fork grants advantage','threshold',{stat:'INT',dc:12,prof:true,advFlag:'fork'},'dispel','drownfight'),O('wade','Face what waits below','Combat · drowned echo · AC 11','threshold',null,'drownfight')]},
threshold:{title:'A door with no lock',chapter:'III / WHAT THE DEAD ARE OWED',text:'Beyond the crypt, hundreds of dead stand in patient silence. Each holds a flower. They part to let you through.\n\nAt the centre of the chamber hangs the lost bell, suspended without rope. Beneath it kneels an old man in a keeper’s coat. His hands have worn through to bone.\n\n“Just once more,” he whispers. “If she hears it, she’ll find her way back.”\n\nNow would be a wise moment to tend your wounds.',options:[O('enter','Approach the bellkeeper','Some doors must be opened gently.','bell')]},
bell:{title:'The bell beneath Blackthorn',chapter:'IV / A NAME IN THE DARK',text:'Edrin looks up. In the hollow of the bell, a shadow turns in the shape of a sleeping woman.\n\n“They tell me to let her go. As if love were a thing you could put down.”\n\nThe bell cracks. Through it, you see a hungry place without a sky. It has been answering in her voice.\n\nThe dead grip their flowers. They are waiting for you to choose.',options:[O('name','Speak the name from the ledger','Requires the remembered name. A peaceful ending.','ending',null,'nameEnding'),O('mercy','Help Edrin say goodbye','Persuasion · CHA + proficiency · DC 14; rescued child grants advantage','ending',{stat:'CHA',dc:14,prof:true,advFlag:'rescued'},'mercyEnding','bossfight'),O('shatter','Shatter the bell’s binding','Arcana · INT + proficiency · DC 13; tuning fork grants advantage','ending',{stat:'INT',dc:13,prof:true,advFlag:'fork'},'shatterEnding','bossfight'),O('battle','Strike the shadow inside the bell','Combat · the hollow grief · AC 13','aftermath',null,'bossfight')]},
aftermath:{title:'After the last note',chapter:'IV / A NAME IN THE DARK',text:'The shadow unravels like smoke in rain. The bell falls into dust. Edrin stares at his empty hands.\n\n“I don’t remember her voice,” he says.\n\nAround you, the dead begin to lie down. There is still one thing to do.',options:[O('stay','Stay with Edrin until dawn','No one should face the silence alone.','ending',null,'stayEnding'),O('return','Return to the village','Carry the living back into the story.','ending',null,'returnEnding')]}
};
const die=(n,rng)=>Math.floor(rng()*n)+1;
function add(s,text,kind='story',title='The Dungeon Master'){s.log.push({text,kind,title});s.log=s.log.slice(-100)}
function flag(s,k,note){if(!s.flags.includes(k)){s.flags.push(k);if(note)s.journal.push(note)}}
function fresh(name,cls){if(!classes[cls])cls='fighter';const c=classes[cls];const s={version:2,name:(name||'Rowan').trim().slice(0,30)||'Rowan',cls,hp:c.hp,maxHp:c.hp,ac:c.ac,slots:cls==='wizard'?3:0,potions:2,gold:10,rested:false,wind:false,hidden:false,ward:false,scene:'road',flags:[],journal:['Reach Blackthorn and learn why the dead are walking.'],log:[],enemy:null,end:null,lastRoll:null,kills:0};add(s,scenes.road.text);return s}
function check(s,spec,rng){const a=die(20,rng),b=spec.advFlag&&s.flags.includes(spec.advFlag)?die(20,rng):null,n=b===null?a:Math.max(a,b),mod=classes[s.cls].stats[spec.stat]+(spec.prof?2:0),total=n+mod,ok=total>=spec.dc;s.lastRoll={n,text:`${spec.stat}: ${b===null?a:`max(${a}, ${b})`} ${mod>=0?'+':'−'} ${Math.abs(mod)} = ${total} vs DC ${spec.dc} · ${ok?'SUCCESS':'FAILURE'}`};add(s,s.lastRoll.text,'roll','Ability check');return ok}
function move(s,next){if(s.end||s.enemy)return;s.scene=next;if(scenes[next])add(s,scenes[next].text)}
function ending(s,title,text){s.end=title;s.enemy=null;add(s,text+'\n\n'+(s.flags.includes('rescued')?'At the village gate, the girl runs to her mother. Your name becomes a story they tell by the hearth.':'Back in Blackthorn, the girl returns with the silent procession. Her mother holds her so tightly that neither can speak.')+'\n\nADVENTURE COMPLETE · '+s.kills+' foes defeated · '+s.gold+' gold carried home.','ending',title);flag(s,'complete',title)}
function enemyTurn(s,rng){if(!s.enemy||s.end)return;if(s.hidden){add(s,'You vanish among the broken stone. Your enemy searches the shadows.','roll','Hidden');return}const e=s.enemy,n=die(20,rng),ac=s.ac+(s.ward?5:0);s.ward=false;const hit=n===20||(n!==1&&n+e.atk>=ac);let damage=0;if(hit){damage=die(e.die,rng)+e.bonus;if(n===20)damage+=die(e.die,rng);s.hp=Math.max(0,s.hp-damage)}add(s,`${e.name}: d20 ${n} + ${e.atk} = ${n+e.atk} vs AC ${ac}. ${hit?(n===20?'Critical hit! ':'')+damage+' damage.':'Miss.'}`,'roll','Enemy turn');if(s.hp===0){s.end='Your story rests here';add(s,'The world narrows to a distant bell. You fought for a village that will remember you.\n\nThis path has ended. Start a new adventure to try another class or another choice.','ending',s.end)}}
function battle(s,kind,next,rng){const specs={guard:{name:'Grave sentinel',hp:13,ac:12,atk:3,die:6,bonus:1,dex:0},drowned:{name:'Drowned echo',hp:15,ac:11,atk:3,die:4,bonus:1,dex:1},boss:{name:'The hollow grief',hp:24,ac:13,atk:4,die:6,bonus:1,dex:1}};s.enemy={...specs[kind],maxHp:specs[kind].hp,next,kind};s.hidden=false;s.ward=false;const a=die(20,rng)+classes[s.cls].stats.DEX,b=die(20,rng)+s.enemy.dex;add(s,`${s.enemy.name} closes in. Your initiative ${a}; enemy ${b}. ${a>=b?'You act first.':'Your enemy acts first.'}`,'roll','Roll initiative');if(a<b)enemyTurn(s,rng)}
function effect(s,id,rng){switch(id){case'promise':flag(s,'promise','You promised to bring Mira’s daughter home.');add(s,'“Lena,” she says. “Her name is Lena.” You repeat it, so she knows you mean it.');break;case'clue':flag(s,'clue','The dead carry flowers. This is a vigil, not an invasion.');add(s,'“Flowers,” she says slowly. “Every one of them was carrying flowers.”');break;case'supplies':s.potions++;s.gold+=5;add(s,'The innkeeper presses a healing potion and five gold into your palm. “Bring them home.”');break;case'rumour':add(s,'The innkeeper will not unbar the door. But through the wood he whispers: “Edrin never buried his wife.”');break;case'oath':flag(s,'oath','The dead are bound to Edrin’s unfinished farewell.');add(s,'You learn the vigil’s oath: the dead may rest only when the keeper releases the last name.');break;case'gravefail':add(s,'Rain has erased the inscriptions. You find only a wilted flower and the tracks of many patient feet.');break;case'child':flag(s,'child','Lena is alive in the abbey cloister.');add(s,'Small footprints run beside larger, skeletal ones. No struggle. The girl walked willingly.');break;case'trackfail':add(s,'The rain has muddied every track. You follow the sound of the bell instead.');break;case'token':add(s,'The sentinel touches the brass token. “Then you have come to help him finish.” It lowers its spear and lets you pass.');break;case'sneak':flag(s,'advantage','You found a hidden passage through the abbey.');add(s,'You pass like a thought through a sleeping mind. The guardian never turns.');break;case'guardfight':battle(s,'guard','cloister',rng);break;case'rescue':flag(s,'rescued','Lena is safe. Edrin may listen to someone who protected a child.');s.gold+=10;add(s,'You guide Lena to Tamsin at the gate. The girl gives you a weed-crown. “For the sad man downstairs.” Tamsin insists you take ten gold for supplies.');break;case'whisper':add(s,'The gardener’s jaw moves without sound. Lena translates: “He says Edrin is lonely.”');break;case'trueName':flag(s,'name','Her name was Avel. The ledger says: “Do not call me back. Live.”');add(s,'Avel. The name settles into you. Beneath it, in another hand: “Do not call me back, my love. Live.”');break;case'ache':add(s,'The note makes your teeth ache. Whatever powers this bell has mistaken grief for an invitation.');break;case'fork':flag(s,'fork','Silver tuning fork: advantage when disrupting the bell’s magic.');add(s,'The fork vibrates in opposition to the bell. A weapon made for undoing, not wounding.');break;case'cache':s.potions+=2;add(s,'You retrieve two healing potions just before the cabinet disappears under falling stone.');break;case'cross':add(s,'You leap the dark water and catch the landing. Pale hands close on empty air below.');break;case'dispel':add(s,'You interrupt the rhythm. The pale shapes settle back into the water like leaves.');break;case'drownfight':battle(s,'drowned','threshold',rng);break;case'nameEnding':ending(s,'THE KINDNESS OF A NAME','“Avel,” you say. Then you read her words.\n\nEdrin’s face crumples. For thirty years he has listened to a thing that could imitate her voice, but never her kindness.\n\nHe lets go. The shadow starves. The bell makes one last, ordinary sound.\n\nAll around you, flowers fall from hands that no longer need to hold them.');break;case'mercyEnding':ending(s,'A DAWN WITHOUT BELLS','You do not tell him that grief will end. You tell him he does not have to carry it alone.\n\nSlowly, Edrin opens his hands. The hungry thing screams with a borrowed voice. He does not answer.\n\nFor the first time in thirty years, Blackthorn hears the birds at dawn.');break;case'shatterEnding':ending(s,'THE SILVER SILENCE','You find the note beneath the note and break it. The bell splits cleanly in two.\n\nThe shadow is pulled into its own hungry dark. Edrin survives, but the last echo of Avel’s voice is gone.\n\n“You saved us,” he says. It takes him a long time to say thank you.');break;case'bossfight':add(s,'The shadow tears free of the bell. It has worn a beloved voice for so long that it has forgotten how to speak in its own.');battle(s,'boss','aftermath',rng);break;case'stayEnding':ending(s,'SOMEONE TO KEEP THE DAWN','You sit beside Edrin until the dark thins. He tells you about Avel: her terrible singing, her impatient laugh, the way she always left the door open.\n\nBy morning, he remembers her voice. Not the shadow’s. Hers.\n\nYou help him climb the stairs.');break;case'returnEnding':ending(s,'THE ROAD HOME','You leave the broken bell behind and climb towards the rain-washed world. Tamsin is waiting at the gate with blankets.\n\nThere will be graves to fill, roofs to mend and stories to tell. Today, that is enough.');break}}
function options(s){if(s.end)return[];if(s.enemy){const list=[{id:'attack',label:s.cls==='wizard'?'Cast Fire Bolt':'Attack with '+classes[s.cls].weapon,hint:`+${classes[s.cls].attack} to hit · 1d${classes[s.cls].die}${classes[s.cls].damage?' + '+classes[s.cls].damage:''}`}];if(s.cls==='fighter'){list.push({id:'power',label:'Power strike',hint:'+3 to hit · 1d8 + 7 damage'});if(!s.wind)list.push({id:'wind',label:'Second Wind',hint:'Heal 1d10 + 2 · does not use your action'})}if(s.cls==='rogue')list.push({id:'hide',label:'Hide in the shadows',hint:'DEX +5 vs DC 11 · prepare sneak attack'});if(s.cls==='wizard'&&s.slots>0)list.push({id:'missile',label:'Cast Magic Missile',hint:'3 × (1d4 + 1) · costs 1 spell slot'},{id:'ward',label:'Cast Mending Ward',hint:'Heal 1d8 + 3 · +5 AC next attack · 1 slot'});list.push({id:'dodge',label:'Dodge',hint:'Enemy attacks with disadvantage for this turn'});if(s.potions)list.push({id:'potion',label:'Drink healing potion',hint:'Heal 2d4 + 2 · takes your action'});list.push({id:'flee',label:'Fall back and regroup',hint:'DEX +2 proficiency vs DC 11; return to the encounter approach'});return list}return scenes[s.scene].options.filter(o=>o.id!=='name'||s.flags.includes('name'))}
function heal(s,amount){const gain=Math.min(s.maxHp-s.hp,amount);s.hp+=gain;return gain}
function combat(s,id,rng){let skip=false;const c=classes[s.cls],e=s.enemy;if(id==='attack'||id==='power'){const a=die(20,rng),b=s.hidden?die(20,rng):null,n=b===null?a:Math.max(a,b),mod=c.attack-(id==='power'?2:0),hit=n===20||(n!==1&&n+mod>=e.ac);let dmg=0;if(hit){dmg=die(c.die,rng)+c.damage+(id==='power'?4:0);if(n===20)dmg+=die(c.die,rng);if(s.hidden&&s.cls==='rogue'){dmg+=die(6,rng);if(n===20)dmg+=die(6,rng)}}s.hidden=false;e.hp=Math.max(0,e.hp-dmg);s.lastRoll={n,text:`Attack: ${b===null?a:`max(${a}, ${b})`} + ${mod} = ${n+mod} vs AC ${e.ac} · ${hit?(n===20?'CRITICAL · ':'')+dmg+' damage':'MISS'}`};add(s,s.lastRoll.text,'roll','Your attack')}
else if(id==='missile'){s.slots--;const dmg=die(4,rng)+die(4,rng)+die(4,rng)+3;e.hp=Math.max(0,e.hp-dmg);add(s,`Three darts of force strike unerringly for ${dmg} damage. ${s.slots} spell slots remain.`,'roll','Magic Missile')}
else if(id==='ward'){s.slots--;s.ward=true;add(s,`Your ward restores ${heal(s,die(8,rng)+3)} HP. +5 AC against the next attack.`,'roll','Mending Ward')}
else if(id==='wind'){s.wind=true;add(s,`You recover ${heal(s,die(10,rng)+2)} HP. You still have your action.`,'roll','Second Wind');return}
else if(id==='hide'){s.hidden=check(s,{stat:'DEX',dc:11,prof:true},rng);add(s,s.hidden?'You disappear. Your next attack has advantage and sneak damage.':'Your boots scrape the stone. The enemy tracks you.')}
else if(id==='dodge'){const a=die(20,rng),b=die(20,rng),n=Math.min(a,b),ac=s.ac+(s.ward?5:0);s.ward=false;const hit=n===20||(n!==1&&n+e.atk>=ac);const dmg=hit?die(e.die,rng)+e.bonus+(n===20?die(e.die,rng):0):0;s.hp=Math.max(0,s.hp-dmg);add(s,`Enemy disadvantage: min(${a}, ${b}) + ${e.atk} = ${n+e.atk} vs AC ${ac}. ${hit?dmg+' damage.':'Miss.'}`,'roll','Dodge');skip=true}
else if(id==='potion'){s.potions--;add(s,`The potion restores ${heal(s,die(4,rng)+die(4,rng)+2)} HP.`,'roll','Healing potion')}
else if(id==='flee'){if(check(s,{stat:'DEX',dc:11,prof:true},rng)){s.enemy=null;s.hidden=false;s.ward=false;add(s,'You retreat beyond its reach. Tend your wounds, then choose how to approach again.');return}else add(s,'Your enemy cuts off the retreat.')}
if(e.hp===0){const next=e.next;s.kills++;s.gold+=e.kind==='boss'?30:8;flag(s,'won-'+e.kind,`Overcame the ${e.name.toLowerCase()}.`);s.enemy=null;s.hidden=false;s.ward=false;add(s,`${e.name} falls. You recover ${e.kind==='boss'?30:8} gold from the scattered offerings.`);move(s,next);return}if(s.hp===0){s.end='Your story rests here';add(s,'The bell fades into darkness. Your adventure ends here. Begin again to walk a different path.','ending',s.end);return}if(!skip)enemyTurn(s,rng)}
function act(s,raw,rng=Math.random){const cmd=raw.trim().toLowerCase();if(!cmd)return s;if(cmd==='help'){add(s,'Choose an action, type its name or number, or use look, journal, potion, rest. Rolls are real random dice, not generated narration. Combat actions and resources appear below.','story','At this table');return s}if(cmd==='journal'){add(s,s.journal.join('\n'),'story','Your journal');return s}if(cmd==='look'){add(s,s.enemy?`${s.enemy.name}: ${s.enemy.hp}/${s.enemy.maxHp} HP · AC ${s.enemy.ac}. Choose a combat action.`:s.end?'Your adventure has ended. Begin a new adventure to try another path.':scenes[s.scene].text);return s}if(s.end)return s;
if(cmd==='rest'){if(s.enemy){add(s,'You cannot rest during combat.');return s}if(s.rested){add(s,'You have already taken your short rest.');return s}if(s.hp===s.maxHp){add(s,'You are already at full health. Save your rest for later.');return s}s.rested=true;add(s,`You bind your wounds in a sheltered corner. Your short rest restores ${heal(s,die(s.cls==='fighter'?10:s.cls==='rogue'?8:6,rng)+cmod(s,'CON')+4)} HP. Spell slots and Second Wind do not refresh in this short adventure.`);return s}
if(cmd==='potion'&&!s.enemy){if(!s.potions){add(s,'Your potion bottles are empty.');return s}if(s.hp===s.maxHp){add(s,'You are already at full health.');return s}s.potions--;add(s,`You drink a potion and restore ${heal(s,die(4,rng)+die(4,rng)+2)} HP.`,'roll','Healing potion');return s}
const opts=options(s);let o=/^[1-9]\d*$/.test(cmd)?opts[Number(cmd)-1]:opts.find(x=>x.id===cmd||x.label.toLowerCase()===cmd);if(!o){add(s,'That action isn’t available here. Use an action’s name or number, or type help. Nothing is spent.','story','A moment to consider');return s}add(s,o.label,'action',s.name);if(s.enemy){combat(s,o.id,rng);return s}const ok=o.check?check(s,o.check,rng):true;const eff=ok?o.success:o.fail;if(eff)effect(s,eff,rng);move(s,o.next);return s}
function cmod(s,key){return classes[s.cls].stats[key]}
const api={classes,scenes,fresh,act,options};if(typeof module!=='undefined')module.exports=api;root.Blackthorn=api;
})(typeof window!=='undefined'?window:globalThis);
